    if (GAME.mapSphere && GAME.mapPlanetOf && GAME.mapPlanetOf() && GAME.mapPlanetOf().id === pid
      && GAME.mapSphere && GAME.mapSphere.cells) return GAME.mapSphere;
    var sp = GAME._extraSpheres[pid];
    if (sp) return sp;
