      var _hfC = (DATA.JIEYUE || {}).tianshouCost || 1;
      var _sp = GAME.jieyueSpend ? GAME.jieyueSpend(_hfC, '问鼎天启体 · ' + g.name) : { ok: false, msg: '节钺系统不可用' };
      if (!_sp.ok) return _sp;
