      t0: now, arriveAt: now + (W.marchRealSec || 3600) * 1000,
      /* v91.50：探索**持续时间**到点（= 抵达 + exploreSec）→ 自动返航（见 wonderTick）。 */
      exploreUntil: 0,   /* 抵达时补算（= arriveAt + exploreSec×1000） */
      acc: [], accrued: 0, returning: false, retArrive: 0,
