    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(poleX, top);
    ctx.lineTo(poleX, by + 7);
    ctx.stroke();
    ctx.beginPath();                             /* 旗面：青碧三角，朝右迎风 */
    ctx.moveTo(poleX, top + 0.4);
    ctx.lineTo(poleX + 7.6, by - 3.6);
    ctx.lineTo(poleX, by + 0.4);
    ctx.closePath();
